<script>
 import {layout,inspectorMax,coverflowMax,saveLayout,resetLayout} from '../layout.svelte';
 import {onMount} from 'svelte';import {KeyRound,FolderOpen,Check,Trash2,RefreshCw} from 'lucide-svelte';import {studio,run,refresh,notify,selectProject} from '../studio.svelte';import {api,persist} from '../api';
 let google=$state(false),deepseek=$state(false),googleKey=$state(''),deepseekKey=$state(''),tools=$state(null),root=$state(''),notifications=$state(typeof Notification!=='undefined'?Notification.permission:'unavailable');
 async function status(){google=await api('credential_status');deepseek=await api('assistant_key_status');tools=await api('assistant_tools');root=studio.dataRoot;}
 onMount(()=>{status().catch(e=>studio.error=e.message);});
 async function keySet(provider){await run('Saving credentials',async()=>{await api(provider==='google'?'credential_set':'assistant_key_set',{key:provider==='google'?googleKey:deepseekKey});googleKey='';deepseekKey='';await status();notify('Key saved to Windows Credential Manager');});}
 async function remove(provider){await run('Removing key',async()=>{await api(provider==='google'?'credential_delete':'assistant_key_delete');await status();notify('Key removed');});}
</script>
<div class="workflow-panel settings-panel"><div class="workflow-heading"><h1>Settings</h1>{#if studio.settingsReturn}<button class="line-button" onclick={()=>{studio.mode=studio.settingsReturn;studio.settingsReturn='';}}>Back to {studio.settingsReturn==='assistant'?'Process':'Generate'}</button>{/if}</div><div class="settings-grid"><section class="settings-block"><h2>Connections</h2><label>Google API key<span class:connected={google}>{google?'Connected':'Not configured'}</span><div class="input-action"><input type="password" autocomplete="off" aria-label="Google API key" bind:value={googleKey} placeholder="Enter key"/><button disabled={!googleKey||!!studio.busy} onclick={()=>keySet('google')}>Save</button></div></label><div class="button-row"><button class="line-button" disabled={!google||!!studio.busy} onclick={()=>run('Testing connection',async()=>{await api('credential_test');notify('Google connection verified');})}>Test connection</button><button disabled={!google||!!studio.busy} aria-label="Remove Google key" onclick={()=>remove('google')}><Trash2 size={15}/></button></div><label>DeepSeek API key<span class:connected={deepseek}>{deepseek?'Connected':'Not configured'}</span><div class="input-action"><input type="password" autocomplete="off" aria-label="DeepSeek API key" bind:value={deepseekKey} placeholder="Enter key"/><button disabled={!deepseekKey||!!studio.busy} onclick={()=>keySet('deepseek')}>Save</button></div></label><button class="line-button" disabled={!deepseek||!!studio.busy} onclick={()=>remove('deepseek')}>Remove DeepSeek key</button><p class="hint">Keys are stored in Windows Credential Manager.</p></section>
<section class="settings-block"><h2>Workspace</h2><div class="field-grid"><label>Inspector width (px)<input aria-label="Inspector width in pixels" type="number" min="220" max={inspectorMax()} value={Math.min(layout.inspectorWidth,inspectorMax())} onchange={e=>{layout.inspectorWidth=Math.min(inspectorMax(),Math.max(220,Number(e.target.value)||280));saveLayout();}}/></label><label>Coverflow height (px)<input aria-label="Coverflow height in pixels" type="number" min="100" max={coverflowMax()} value={Math.min(layout.coverflowHeight,coverflowMax())} onchange={e=>{layout.coverflowHeight=Math.min(coverflowMax(),Math.max(100,Number(e.target.value)||144));saveLayout();}}/></label></div><button class="text-button" onclick={resetLayout}>Reset panel layout</button><label>Data folder<div class="input-action"><input aria-label="Data folder" bind:value={root}/><button aria-label="Choose data folder" onclick={()=>run('Choosing folder',async()=>{const path=await api('pick_output');if(path)root=path;})}><FolderOpen size={16}/></button></div></label><button class="line-button" disabled={!root||root===studio.dataRoot||!!studio.busy} onclick={()=>run('Switching workspace',async()=>{await api('data_root_switch',{path:root});studio.pid='';studio.aid='';studio.drafts={};studio.selected=[];await refresh();notify('Workspace switched');})}>Use this folder</button><label>Canvas<select bind:value={studio.background} onchange={()=>persist('background',studio.background)}><option value="paper">Paper</option><option value="checker">Transparency</option><option value="dark">Dark</option></select></label><label>Desktop notifications<button class="line-button" disabled={notifications==='granted'||notifications==='unavailable'} onclick={async()=>notifications=await Notification.requestPermission()}>{notifications==='granted'?'Enabled':'Enable notifications'}</button></label><label>Preview acceleration<select aria-label="Preview acceleration" bind:value={studio.gpuPreviewEnabled} onchange={()=>persist('gpu-preview-enabled',studio.gpuPreviewEnabled)}><option value={true}>GPU when available</option><option value={false}>CPU compatibility</option></select></label><div class="status-line"><span>Preview engine</span><b>{studio.previewEngine==='gpu'?'GPU ready':studio.previewEngine==='cpu'?'CPU':'Checking'}</b></div><h3>Local tools</h3><div class="status-line"><span>Rust image engine</span><b class="connected">Ready</b></div><div class="status-line"><span>OpenCV</span><b>{tools?(tools.available?'Ready':'Unavailable'):'Checking'}</b></div>{#if tools&&!tools.available}<p class="hint">{tools.error||tools.message||'Configure Python with OpenCV to use denoise.'}</p>{/if}</section>
<section class="settings-block"><h2>Costs</h2><div class="field-grid"><label>Currency<select bind:value={studio.currency} onchange={()=>persist('currency',studio.currency)}><option>USD</option><option>CNY</option></select></label><label>USD → CNY<input type="number" min=".01" step=".01" bind:value={studio.exchangeRate} onchange={()=>persist('exchangeRate',studio.exchangeRate)}/></label></div><div class="model-table">{#each studio.catalog?.models||[] as model}<div><b>{model.name}</b><small>{model.id}</small><span>{model.resolutions.join(' / ')}</span><span>{model.imageUsd?.['1K']!=null?`$${model.imageUsd['1K']} / 1K`:'Price unavailable'}</span></div>{/each}</div><p class="hint">Estimates use the model catalog. Final costs depend on returned usage.</p></section>
<section class="settings-block"><h2>Shortcuts</h2>{#each [['Ctrl + S','Save version'],['Ctrl + Z','Undo'],['Ctrl + Shift + Z','Redo'],['Ctrl + 1–4','Change workspace'],['Q / E','Change tool'],['← / →','Previous / next image'],['Ctrl + wheel','Zoom'],['0','Fit image'],['\\','Hold original'],['Right click','Tool menu']] as [key,label]}<div class="shortcut"><span>{label}</span><kbd>{key}</kbd></div>{/each}</section></div></div>
